// ATK-L50 minesweeper board: RGB LCD + I2C touch + UART console.
// The LCD picture is generated by lcd_mine_display from a packed 9x9 tile map
// that the firmware writes through MMIO 0x1000_00A0..0x1000_00DC.
module atk_l50_mine #(
    parameter MEM_FILE     = "software/build/mine/firmware.hex",
    parameter TOUCH_ENABLE = 1,
    parameter integer CLK_HZ = 50_000_000,
    parameter integer BAUD = 115_200,
    parameter integer TOUCH_SCL_HZ = 100_000,
    parameter FONT_FILE = "rtl/periph/mine_font.hex",
    parameter integer LCD_RESET_CYCLES = 500_000
) (
    input  wire       sys_clk,
    input  wire       sys_rst_n,
    input  wire [3:0] key,
    output wire       uart_txd,
    output wire [3:0] led,
    output wire       lcd_pclk,
    output wire       lcd_de,
    output wire       lcd_hs,
    output wire       lcd_vs,
    output wire       lcd_rst,
    output wire       lcd_bl,
    output wire [23:0] lcd_rgb,
    output wire       tp_scl,
    inout  wire       tp_sda,
    output wire       tp_rst,
    inout  wire       tp_int
);
    wire rst_n, tick, halted, trap;
    wire [9:0] x;
    wire [8:0] y;
    wire [23:0] pixel;
    wire [31:0] frames;
    wire [511:0] mine_state;
    wire [1023:0] sprites_unused;
    wire [127:0]  hud_unused;
    wire [7:0] gpio;

    wire tp_scl_o, tp_sda_o, tp_sda_oe, tp_sda_i, tp_int_o, tp_int_oe, tp_rst_o;

    (* syn_preserve=1 *) reg [3:0] key_meta, key_sync;
    reset_sync u_reset (.clk_i(sys_clk), .reset_n_i(sys_rst_n), .reset_n_o(rst_n));
    always @(posedge sys_clk or negedge rst_n) begin
        if (!rst_n) begin
            key_meta <= 15;
            key_sync <= 15;
        end else begin
            key_meta <= key;
            key_sync <= key_meta;
        end
    end

    assign tp_sda   = (tp_sda_oe && !tp_sda_o) ? 1'b0 : 1'bz;
    assign tp_sda_i = tp_sda;
    assign tp_scl   = tp_scl_o;
    assign tp_rst   = tp_rst_o;
    assign tp_int   = tp_int_oe ? tp_int_o : 1'bz;

    rv32i_soc #(
        .CLOCK_HZ    (CLK_HZ),
        .BAUD        (BAUD),
        .MEM_FILE    (MEM_FILE),
        .LCD_ENABLE  (0),
        .VIDEO_ENABLE(1),
        .MINE_ENABLE (1),
        .TOUCH_ENABLE(TOUCH_ENABLE),
        .TOUCH_SCL_HZ(TOUCH_SCL_HZ)
    ) u_soc (
        .clk_i          (sys_clk),
        .rst_n_i        (rst_n),
        .key_i          (key_sync),
        .uart_tx_o      (uart_txd),
        .gpio_o         (gpio),
        .halted_o       (halted),
        .trap_o         (trap),
        .video_frame_i  (tick),
        .video_sprites_o(sprites_unused),
        .video_hud_o    (hud_unused),
        .video_mine_o   (mine_state),
        .tp_scl_o       (tp_scl_o),
        .tp_sda_o       (tp_sda_o),
        .tp_sda_oe      (tp_sda_oe),
        .tp_sda_i       (tp_sda_i),
        .tp_int_i       (tp_int),
        .tp_rst_o       (tp_rst_o),
        .tp_int_o       (tp_int_o),
        .tp_int_oe      (tp_int_oe)
    );

    assign led = trap ? 4'hf : gpio[3:0];

    lcd_800x480 #(.RESET_CYCLES(LCD_RESET_CYCLES)) u_lcd (
        .clk_i          (sys_clk),
        .rst_n_i        (rst_n),
        .pixel_i        (pixel),
        .x_o            (x),
        .y_o            (y),
        .frame_tick_o   (tick),
        .frame_count_o  (frames),
        .lcd_pclk       (lcd_pclk),
        .lcd_de         (lcd_de),
        .lcd_hs         (lcd_hs),
        .lcd_vs         (lcd_vs),
        .lcd_rst        (lcd_rst),
        .lcd_bl         (lcd_bl),
        .lcd_rgb        (lcd_rgb)
    );

    lcd_mine_display #(.FONT_FILE(FONT_FILE)) u_display (
        .clk_i  (sys_clk),
        .x_i    (x),
        .y_i    (y),
        .mine_i (mine_state),
        .rgb_o  (pixel)
    );
endmodule
